// #13/AK7: generates the pseudo language for UI tests (integration_test/pseudo_localizations.dart) from
// the English texts that gen-l10n writes (lib/l10n/app_localizations_en.dart): every text of
// AppLocalizations goes through pseudo() (integration_test/pseudo.dart). test/pseudo_l10n_test.dart
// fails when the generated file is out of date (compared without formatting).
// Usage (in app/, after flutter gen-l10n): dart run tool/pseudo_l10n.dart
import 'dart:io';

const englishFile = 'lib/l10n/app_localizations_en.dart';
const outputFile = 'integration_test/pseudo_localizations.dart';

final _member = RegExp(
  r'@override\s+String\s+(?:get\s+(\w+)\s*=>|(\w+)\(([^)]*)\)\s*(?:=>|\{))',
);

/// The members of the English class: getter name, or method name with its parameter list.
List<(String name, String? params)> englishMembers(String source) => [
  for (final m in _member.allMatches(source))
    m.group(1) != null ? (m.group(1)!, null) : (m.group(2)!, m.group(3)!),
];

/// The generated Dart file for [englishSource].
String generate(String englishSource) {
  final b = StringBuffer()
    ..writeln(
      '// GENERATED by tool/pseudo_l10n.dart from $englishFile, do not edit',
    )
    ..writeln(
      '// (#13/AK7). Regenerate in app/: dart run tool/pseudo_l10n.dart',
    )
    ..writeln('// ignore_for_file: type=lint')
    ..writeln("import 'package:flutter/foundation.dart';")
    ..writeln("import 'package:material_ui/material_ui.dart';")
    ..writeln("import 'package:woodshed_player/l10n/app_localizations.dart';")
    ..writeln(
      "import 'package:woodshed_player/l10n/app_localizations_en.dart';",
    )
    ..writeln()
    ..writeln("import 'pseudo.dart';")
    ..writeln()
    ..writeln('/// The English texts in the pseudo language.')
    ..writeln('class PseudoLocalizations extends AppLocalizationsEn {');
  for (final (name, params) in englishMembers(englishSource)) {
    b.writeln('  @override');
    if (params == null) {
      b.writeln('  String get $name => pseudo(super.$name);');
    } else {
      final args = params
          .split(',')
          .map((p) => p.trim().split(RegExp(r'\s+')).last)
          .where((p) => p.isNotEmpty)
          .join(', ');
      b.writeln('  String $name($params) => pseudo(super.$name($args));');
    }
  }
  b
    ..writeln('}')
    ..writeln()
    ..writeln('/// Loads [PseudoLocalizations] for any locale.')
    ..writeln(
      'class PseudoLocalizationsDelegate '
      'extends LocalizationsDelegate<AppLocalizations> {',
    )
    ..writeln('  const PseudoLocalizationsDelegate();')
    ..writeln('  @override')
    ..writeln('  bool isSupported(Locale locale) => true;')
    ..writeln('  @override')
    ..writeln('  Future<AppLocalizations> load(Locale locale) =>')
    ..writeln('      SynchronousFuture(PseudoLocalizations());')
    ..writeln('  @override')
    ..writeln('  bool shouldReload(PseudoLocalizationsDelegate old) => false;')
    ..writeln('}');
  return b.toString();
}

void main() {
  final source = File(englishFile).readAsStringSync();
  File(outputFile).writeAsStringSync(generate(source));
  Process.runSync('dart', ['format', outputFile]);
  stdout.writeln('$outputFile: ${englishMembers(source).length} texts');
}
